import {Link,useParams} from 'react-router-dom';import {useApi} from '../../lib/useApi';import DataTable from '../../components/DataTable';import Pill from '../../components/Pill';import IdentityCardPanel from '../../components/IdentityCardPanel';
export default function VendorDetailPage(){const {businessId}=useParams(),{data,loading,error,reload}=useApi(`/vendors/${businessId}`),v=data?.vendor;if(loading)return <p>Loading...</p>;if(error)return <div className="error-banner">{error}</div>;if(!v)return null;const ordered=(v.purchaseOrders||[]).reduce((n,x)=>n+Number(x.total||0),0),paid=(v.purchaseOrders||[]).reduce((n,x)=>n+Number(x.amount_paid||0),0);return <div><Link className="breadcrumb-link" to="/vendors">← All vendors</Link><div className="card-header"><div><h1 className="page-title">{v.business_id} — {v.name}</h1><p className="card-subtitle">Permanent vendor profile and complete procurement history</p></div><Pill status={v.status}/></div><div className="stats-grid"><div className="stat-card"><div className="stat-label">Total ordered</div><div className="stat-value">BDT {ordered.toLocaleString()}</div></div><div className="stat-card"><div className="stat-label">Total paid</div><div className="stat-value">BDT {paid.toLocaleString()}</div></div><div className="stat-card"><div className="stat-label">Outstanding</div><div className="stat-value">BDT {(ordered-paid).toLocaleString()}</div></div></div><div className="card" style={{marginTop:18}}><h3>Vendor information</h3><p><strong>Type:</strong> {v.vendor_type||'Not specified'} · <strong>Phone:</strong> {v.phone||'—'} · <strong>Email:</strong> {v.email||'—'}</p><p><strong>Address:</strong> {v.address||'—'}</p></div><IdentityCardPanel entityType="VENDOR" record={v} name={v.name} onUpdated={reload}/><div className="card"><h3>Purchase orders and receiving</h3><DataTable rows={v.purchaseOrders||[]} emptyMessage="No purchase orders." columns={[{key:'business_id',label:'PO',render:x=><Link to={`/procurement/purchase-orders/${x.business_id}`}>{x.business_id}</Link>},{key:'destination_name',label:'Receiver'},{key:'total',label:'Total',render:x=>`BDT ${Number(x.total).toLocaleString()}`},{key:'amount_paid',label:'Paid',render:x=>`BDT ${Number(x.amount_paid).toLocaleString()}`},{key:'status',label:'Status',render:x=><Pill status={x.status}/>} ]}/></div><div className="card"><h3>Payments</h3><DataTable rows={v.payments||[]} emptyMessage="No payments." columns={[{key:'purchase_order_business_id',label:'PO'},{key:'amount',label:'Amount',render:x=>`BDT ${Number(x.amount).toLocaleString()}`},{key:'account_name',label:'Account'},{key:'payment_date',label:'Date',render:x=>new Date(x.payment_date).toLocaleDateString()}]}/></div><div className="card"><h3>Submitted bills</h3><DataTable rows={v.bills||[]} emptyMessage="No vendor bills." columns={[{key:'business_id',label:'Bill',render:x=><Link to={`/bills/${x.business_id}`}>{x.business_id}</Link>},{key:'bill_type',label:'Type'},{key:'total_amount',label:'Amount',render:x=>`BDT ${Number(x.total_amount).toLocaleString()}`},{key:'status',label:'Status',render:x=><Pill status={x.status}/>} ]}/></div></div>}
